with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , DATE_PAY_RECEIVED as PREMIUM_REALISATION_DATE
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (nullif(trim(POLICY_REF),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then PREMIUM_REALISATION_DATE end) as PREMIUM_REALISATION_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when PREMIUM_REALISATION_DATE is not null
                     then md5(upper(coalesce(cast(PREMIUM_REALISATION_DATE as varchar), '')))
                end as SAT_POLICY_PREMIUM_SETTLEMENT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_PREMIUM_SETTLEMENT_HASHDIFF is not null
